// ==== Settings ===============================================================
const MONTHS = [];  // e.g. ['2018-03'] to explain a few months; empty = every month that moved
const KPIS = [];    // e.g. ['late_delivery_rate']; empty = every enabled KPI in insights.kpi_config
// =============================================================================

const runId = 'explain_' + new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
return [{ json: { run_id: runId, months: MONTHS, kpis: KPIS, full: MONTHS.length === 0 } }];

