// The month against its baseline and the breakdown totals. No raw orders are sent.
const m = $('Each month').first().json;
const cuts = $input.first().json.cuts;
const pct = v => v == null ? 'n/a' : (100 * Number(v)).toFixed(1) + '%';
const label = new Date(m.month + 'T00:00:00Z').toLocaleString('en-GB', { month: 'long', year: 'numeric', timeZone: 'UTC' });
const show = value => Object.entries(value).map(([c, v]) => `${c}=${v ?? 'null'}`).join(', ');
const lines = [
  `KPI: ${m.name} (${m.kpi_id}). ${m.definition}`,
  `Gap orders: ${m.gap_noun}. Cross-KPI effect measured for each cause: ${m.impact?.noun ?? 'none'}.`,
  `Month: ${label}. ${m.name}: ${pct(m.rate)}, against ${pct(m.baseline_rate)} in a normal month ` +
    `(median of the 3 months before), ${m.ratio} times as high.`,
  `Orders: ${m.orders}, against ${m.prev_orders ?? 'n/a'} the month before. ${m.counted} orders count for the KPI, ` +
    `${m.gap_orders} of them ${m.gap_noun}: about ${Math.round(m.counted * (m.rate - m.baseline_rate))} more than at ` +
    'the normal rate.',
  '',
  `Approved columns: ${m.columns.join(', ')}`,
  'Levers:',
  ...Object.entries(m.levers).map(([k, v]) => `- ${k}: ${v}`),
  '',
  'Breakdowns. Each row: value | orders | gap orders and rate this month | rate of the same orders in a normal month | ' +
    'share of the month\'s gap orders | gap orders above normal:',
];
// Single columns in the order of the KPI settings, then the pairs
const order = name => { const i = m.columns.indexOf(name); return i < 0 ? m.columns.length : i; };
for (const [name, rows] of Object.entries(cuts).sort(([a], [b]) => order(a) - order(b))) {
  lines.push('', `[${name}]`);
  for (const r of rows) {
    lines.push(`- ${show(r.value)} | ${r.orders} | ${r.gap_orders} = ${pct(r.rate)} | normal ${pct(r.baseline_rate)} | ` +
               `${pct(r.share_of_gap)} of ${m.gap_noun} | ${r.excess_gap_orders > 0 ? '+' : ''}${r.excess_gap_orders}`);
  }
}
return [{ json: { prompt: lines.join('\n') } }];

// Checks without AI, item by item, then builds the query that measures every cause that is well formed.
// An item that fails can be repaired once; the rest of the answer is kept.
const m = $('Each month').first().json;
const cuts = $('Run breakdowns').first().json.cuts;
const out = $input.first().json;
// n8n's Postgres node fills {{ }} with String.replace, which reads $' $& $` $$ in the value as patterns, so a
// literal never contains a $: it is written as chr(36), which gives the same text.
const lit = v => { const s = String(v).replace(/'/g, "''");
                   return s.includes('$') ? `(${s.split('$').map(p => `'${p}'`).join(' || chr(36) || ')})` : `'${s}'`; };
const MONTH_KEYS = ['month', 'month_rate', 'month_baseline_rate', 'orders', 'prev_orders', 'orders_change'];
const CAUSE_KEYS = [...MONTH_KEYS, 'rate', 'baseline_rate', 'matched_orders', 'gap_orders', 'share_of_gap',
                    'excess_gap_orders', 'points_recovered', 'impact_recovered'];
const RECO_KEYS = [...MONTH_KEYS, 'points_recovered'];
const KEY = /^[a-z][a-z0-9_]{2,59}$/;
const cutNames = Object.keys(cuts);

function textProblems(text, allowed) {
  const s = String(text ?? '').trim();
  if (!s) return ['the text is empty'];
  const problems = [];
  const bare = s.replace(/\{[a-z_]+\}/g, '');
  if (/\d/.test(bare)) problems.push('the text has a number in it; use a placeholder');
  const unknown = [...s.matchAll(/\{([a-z_]+)\}/g)].map(x => x[1]).filter(k => !allowed.includes(k));
  if (unknown.length) problems.push(`placeholders not allowed here: ${unknown.map(k => `{${k}}`).join(', ')}`);
  if (/[{}]/.test(bare)) problems.push('the text has a { or } that is not a placeholder');
  return problems;
}
const cutProblems = list => !Array.isArray(list) || list.length === 0 ? ['name at least one breakdown in supporting_cuts']
  : list.filter(c => !cutNames.includes(c)).map(c => `"${c}" is not a breakdown`);

const errors = [];  // { item, key, problems }
const answer = out.output ?? null;
if (!answer) {
  errors.push({ item: 'answer', key: 'answer', problems: [
    out.error ? `the agent failed: ${out.error.message ?? out.error}` : 'no answer was returned'] });
}
const a = answer ?? { what_happened: '', ruled_out: [], causes: [], recommendations: [] };

const p = textProblems(a.what_happened, MONTH_KEYS);
if (answer && p.length) errors.push({ item: 'what_happened', key: 'what_happened', problems: p });

(a.ruled_out ?? []).forEach((r, i) => {
  const cutsNamed = r.supporting_cuts ?? [];
  const problems = [...textProblems(r.factor, []), ...textProblems(r.reason, MONTH_KEYS),
                    ...(cutsNamed.length ? cutProblems(cutsNamed) : [])];
  if (problems.length) errors.push({ item: 'ruled_out', key: r.factor || `ruled_out_${i + 1}`, problems });
});

const causes = (a.causes ?? []).map(c => ({ ...c,
  filter: (c.cause_filter ?? []).map(f => ({ column: f.column, op: f.op,
                                             value: f.op === 'in' ? (f.values ?? []) : (f.values ?? [])[0] })) }));
if (answer && causes.length === 0) errors.push({ item: 'causes', key: 'causes', problems: ['name at least one cause'] });
const seen = new Set();
for (const c of causes) {
  const problems = [];
  if (!KEY.test(c.cause_key ?? '')) problems.push('cause_key must be lower_snake_case');
  if (seen.has(c.cause_key)) problems.push('cause_key is used twice');
  seen.add(c.cause_key);
  problems.push(...textProblems(c.cause_name, []).map(x => `cause_name: ${x}`),
                ...textProblems(c.explanation, CAUSE_KEYS).map(x => `explanation: ${x}`),
                ...cutProblems(c.supporting_cuts));
  const raw = c.cause_filter ?? [];
  if (raw.length < 1 || raw.length > 3) problems.push('the filter needs one to three conditions');
  for (const f of raw) {
    if (!m.columns.includes(f.column)) problems.push(`column "${f.column}" is not approved; allowed: ${m.columns.join(', ')}`);
    const n = (f.values ?? []).length;
    if (f.op === 'in' ? n < 1 : n !== 1) problems.push(`column "${f.column}": op ${f.op} needs ${f.op === 'in' ? 'one or more values' : 'exactly one value'}`);
  }
  if (problems.length) errors.push({ item: 'cause', key: c.cause_key, problems });
}

const levers = Object.keys(m.levers);
const causeKeys = new Set(causes.map(c => c.cause_key));
const recoSeen = new Set();
for (const r of a.recommendations ?? []) {
  const problems = [];
  if (!KEY.test(r.reco_key ?? '')) problems.push('reco_key must be lower_snake_case');
  if (recoSeen.has(r.reco_key)) problems.push('reco_key is used twice');
  recoSeen.add(r.reco_key);
  if (!levers.includes(r.lever)) problems.push(`lever "${r.lever}" is not in the list: ${levers.join(', ')}`);
  problems.push(...textProblems(r.action, RECO_KEYS).map(x => `action: ${x}`));
  const closes = r.closes_cause_keys ?? [];
  if (closes.length === 0) problems.push('closes_cause_keys is empty');
  const unknown = closes.filter(k => !causeKeys.has(k));
  if (unknown.length) problems.push(`closes causes that do not exist: ${unknown.join(', ')}`);
  if (problems.length) errors.push({ item: 'recommendation', key: r.reco_key, problems });
}

// Measure every cause whose filter is well formed, plus the whole month (empty filter) to reconcile with kpi_months
const failedCauses = new Set(errors.filter(e => e.item === 'cause').map(e => e.key));
const toSize = causes.filter(c => !failedCauses.has(c.cause_key));
const values = [`('__all__', '[]')`, ...toSize.map(c => `(${lit(c.cause_key)}, ${lit(JSON.stringify(c.filter))})`)];
const sizing_sql = `select v.k as key, insights.size_cause(${lit(m.kpi_id)}, ${lit(m.month)}::date, v.f::jsonb) as s\n` +
                   `from (values ${values.join(', ')}) v(k, f);`;
return [{ json: { origin: 'agent', attempt: 1,
                  answer: { ...a, causes }, errors, sizing_sql } }];

// Adds the measured numbers and the checks that need them. A cause must match gap orders and have more of them than
// in a normal month. The whole month must reconcile with kpi_months; if not, the data changed under the run (a system
// error, never sent to the agent).
const m = $('Each month').first().json;
const c = $('Check answer').first().json;
const size = {};
for (const row of $input.all().map(i => i.json)) size[row.key] = typeof row.s === 'string' ? JSON.parse(row.s) : row.s;
const all = size.__all__;
const system_errors = [];
if (!all?.ok) system_errors.push(`the month could not be measured: ${all?.error ?? 'no result'}`);
else if (all.gap_orders !== m.gap_orders || all.matched_orders !== m.counted)
  system_errors.push(`sizing does not reconcile with kpi_months: ${all.matched_orders} orders / ${all.gap_orders} ` +
                     `${m.gap_noun}, expected ${m.counted} / ${m.gap_orders}`);

const errors = [...c.errors];
const failed = new Set(errors.filter(e => e.item === 'cause').map(e => e.key));
for (const cause of c.answer.causes) {
  if (failed.has(cause.cause_key)) continue;
  const s = size[cause.cause_key];
  const problems = [];
