  else if (s.gap_orders === 0) problems.push(`the filter matches no ${m.gap_noun} this month`);
  else if (s.excess_gap_orders <= 0) problems.push(`these orders were not ${m.gap_noun.replace(/ orders$/, '')} more often ` +
                                                   'than in a normal month, so they do not explain the rise');
  if (problems.length) { errors.push({ item: 'cause', key: cause.cause_key, problems }); failed.add(cause.cause_key); }
}
for (const r of c.answer.recommendations ?? []) {
  const lost = (r.closes_cause_keys ?? []).filter(k => failed.has(k));
  if (lost.length && !errors.some(e => e.item === 'recommendation' && e.key === r.reco_key))
    errors.push({ item: 'recommendation', key: r.reco_key, problems: [`closes a cause that was rejected: ${lost.join(', ')}`] });
}
return [{ json: { ...c, size, errors, system_errors, reconciled: system_errors.length === 0,
                  passed: system_errors.length === 0 && errors.length === 0 } }];

// One second chance: the agent sees its answer and exactly which items were rejected, and why
const r = $('Read checks').first().json;
const prompt = [
