  '',
  'Your previous answer:',
  JSON.stringify($('Explain agent').first().json.output ?? null),
  '',
  'These items were rejected:',
  ...r.errors.map(e => `- ${e.item} "${e.key}": ${e.problems.join('; ')}`),
  '',
