const summary = { ...base, kpi_name: m.name, headline, rate: m.rate, baseline_rate: m.baseline_rate, orders: m.orders,
                  prev_orders: m.prev_orders, causes: causes.length, status };
const causeRows = causes.map((c, i) => ({ ...base, kind: 'cause', cause_key: c.cause_key, cause_name: c.cause_name,
  explanation: fill(c.explanation, causeValues(c.s)), cause_filter: c.filter, supporting_cuts: c.supporting_cuts,
  matched_orders: c.s.matched_orders, gap_orders: c.s.gap_orders, rate: c.s.rate, baseline_rate: c.s.baseline_rate,
  share_of_gap: c.s.share_of_gap, points_recovered: c.s.points_recovered, impact_recovered: c.s.impact_recovered,
  rank: i + 1, ...drill(c) }));
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 50) || 'factor';
const ruledRows = ruled.map((x, i) => ({ ...base, kind: 'ruled_out', cause_key: `${slug(x.factor)}_${i + 1}`,
  cause_name: x.factor, explanation: fill(x.reason, monthValues), supporting_cuts: x.supporting_cuts }));
const names = Object.fromEntries(causes.map(c => [c.cause_key, c.cause_name]));
const recoRows = recos.map((x, i) => ({ ...base, reco_key: x.reco_key, lever: x.lever,
  action: fill(x.action, { ...monthValues, points_recovered: Number(x.points).toFixed(1) }),
  closes_cause_keys: x.closes_cause_keys, closes_cause_names: x.closes_cause_keys.map(k => names[k]).join('; '),
  points_recovered: x.points, rank: i + 1 }));

const dropped = r.errors.map(e => `${e.item} "${e.key}" (${e.problems.join('; ')})`);
const log = {
  run_id: run.run_id, agent: 'insights', action: 'explain_month', source: `${m.kpi_id} ${m.month.slice(0, 7)}`,
  target_table: 'analytics.insight_causes', status: status === 'explained' ? 'success' : 'warning',
  rows_read: null, rows_written: 1 + causeRows.length + ruledRows.length + recoRows.length, duration_ms: null,
  reason: `${m.name} ${label}: ${causes.length} cause${causes.length === 1 ? '' : 's'}, ${ruledRows.length} ruled out, ` +
          `${recoRows.length} action${recoRows.length === 1 ? '' : 's'}` +
          (r.attempt === 2 ? ", after the agent's repair try" : '') +
          (dropped.length ? `. Dropped: ${dropped.join('; ')}` : ''),
  details: { attempt: r.attempt, answer: a, dropped: r.errors,
             causes: causes.map(c => ({ key: c.cause_key, filter: c.filter, size: c.s })) },
};
const insert = (table, row) => {
  const cols = Object.keys(row);
  return `insert into ${table} (${cols.join(', ')}) select ${cols.join(', ')} ` +
         `from jsonb_populate_record(null::${table}, ${lit(JSON.stringify(row))}::jsonb);`;
};
const save_sql = [
  insert('insights.stage_summary', summary),
  ...causeRows.map(x => insert('insights.stage_causes', x)),
  ...ruledRows.map(x => insert('insights.stage_causes', x)),
  ...recoRows.map(x => insert('insights.stage_recommendations', x)),
  insert('ops.agent_logs', log),
  'select 1 as saved;',
].join('\n');
return [{ json: { status, causes: causes.length, save_sql } }];

// The month does not reconcile: the analytics tables changed while the run was going, or the KPI settings are wrong
const run = $('Settings').first().json;
const m = $('Each month').first().json;
const r = $('Read checks').first().json;
return [{ json: {
  run_id: run.run_id, agent: 'insights', action: 'run_complete', source: null, target_table: null,
  status: 'failed', rows_read: null, rows_written: null, duration_ms: null,
  reason: `Stopped at ${m.kpi_id} ${m.month.slice(0, 7)}: ${r.system_errors.join('; ')}. Nothing was published: ` +
          'the insight tables still hold the last good run.',
  details: JSON.stringify({ kpi_id: m.kpi_id, month: m.month, system_errors: r.system_errors }),
} }];

const run = $('Settings').first().json;
const months = $input.all().map(i => i.json).filter(x => x.month);
const by = s => months.filter(x => x.status === s).length;
return [{ json: {
  run_id: run.run_id, agent: 'insights', action: 'run_complete', source: null, target_table: null,
  status: by('explained') === months.length ? 'success' : 'warning', rows_read: null, rows_written: months.length,
  duration_ms: null,
  reason: `${months.length} month${months.length === 1 ? '' : 's'} explained and published (` +
          months.map(x => `${x.kpi_id} ${x.month}: ${x.causes} cause${x.causes === 1 ? '' : 's'}`).join(', ') + ')' +
          (by('partly_explained') ? `; ${by('partly_explained')} with items dropped` : '') +
          (by('not_explained') ? `; ${by('not_explained')} without a cause that passed` : ''),
  details: JSON.stringify({ months, full: run.full }),
} }];
